s = s.replace(old, new)

# 3) таблица репозиториев (строка kip8test была stale v655)
old = '| `kip8test` | PWA | `kipia-test-v655` | — | Активная разработка, проверка перед боем |'
new = '| `kip8test` | PWA | `kipia-test-v666` | — | Активная разработка, проверка перед боем |'
