# 4) формат бампа в правиле SW
old = "Формат: `kipia-test-v665` → `kipia-test-v666` (для kip8test) или `kipia-v479` → `kipia-v480` (для kip8)"
new = "Формат: `kipia-test-v666` → `kipia-test-v667` (для kip8test) или `kipia-v480` → `kipia-v481` (для kip8)"
