# 5) счётчик тестов
old = "# Ожидается: 4586 passed, 0 failed (kip8test; в kip8 — 4472 passed, 0 failed)"
new = "# Ожидается: 4602 passed, 0 failed (kip8test; в kip8 — 4592 passed, 0 failed)"
